  -- ord 1992: trench-safety-1 (edited in place)
  update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "trench-safety-1", "url": "https://www.osha.gov/trenching-excavation", "text": "Under OSHA's excavation standard (29 CFR 1926.652), workers in an excavation must be protected from cave-ins by a protective system (sloping, benching, shoring or a shield/trench box) unless the excavation is made entirely in stable rock, or is less than 5 ft deep and a competent person has examined the ground and found no sign of a potential cave-in. Excavations 20 ft deep or more need a protective system designed by a registered professional engineer (or based on tabulated data approved by one). OSHA's trenching page stresses that trench collapses kill workers every year and that a cubic yard of soil can weigh as much as a car. Never enter an unprotected trench 5 ft or deeper, and don't assume shallow trenches are safe; a state plan can set a shallower depth, so check the job's state. Some state plans are stricter than federal OSHA; your competent person and company program decide. This is a plain-language explanation, not the regulation; the OSHA text governs.", "title": "Trench safety: when a protective system is required", "topic": "Trench and excavation safety (plain-language guidance)", "source": "OSHA Trenching and Excavation safety topic page", "confidence": "high"}$kb$::jsonb
   where version = 'b3e91f6c47d2' and ord = 1992 and chunk->>'id' = $kb$trench-safety-1$kb$ and md5(chunk::text) = md5($kb${"id": "trench-safety-1", "url": "https://www.osha.gov/trenching-excavation", "text": "Under OSHA's excavation standard (29 CFR 1926.652), workers in an excavation must be protected from cave-ins by a protective system (sloping, benching, shoring or a shield/trench box) unless the excavation is made entirely in stable rock, or is less than 5 ft deep and a competent person has examined the ground and found no sign of a potential cave-in. Excavations 20 ft deep or more need a protective system designed by a registered professional engineer (or based on tabulated data approved by one). OSHA's trenching page stresses that trench collapses kill workers every year and that a cubic yard of soil can weigh as much as a car. Never enter an unprotected trench 5 ft or deeper (4 ft or deeper in Washington, WAC 296-155-657), and don't assume shallow trenches are safe. Some state plans are stricter than federal OSHA; your competent person and company program decide. This is a plain-language explanation, not the regulation; the OSHA text governs.", "title": "Trench safety: when a protective system is required", "topic": "Trench and excavation safety (plain-language guidance)", "source": "OSHA Trenching and Excavation safety topic page", "confidence": "high"}$kb$::jsonb::text);
  get diagnostics vk = row_count; if vk <> 1 then raise exception 'FAIL: row % is not the expected live text', 1992; end if;
  -- ord 2835: dig-basics-1 (edited in place)
  update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-basics-1", "url": "https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.651", "text": "Every state has a one-call law and 811 reaches the right center from anywhere in the country. The steps are the same everywhere: mark your dig area in white, call or go online before you dig, wait the legal notice time, check that every utility has marked or answered, dig by hand or vacuum inside the tolerance zone, keep the marks visible, and renew the ticket before it runs out. What changes by state is the numbers. No federal law sets the wait, the ticket life or the tolerance zone. The wait runs from 48 hours to 5 working days; ticket life runs from about two weeks to 60 days, counted in working days in some states and calendar days in others, and from the call in some and from the legal dig date in others; the tolerance zone is 18 or 24 inches each side in nearly every state, measured from the mark in some and from the outside edge of the line in others. The 811 by-state tables list each state's numbers. So never carry one state's numbers to the next job: ask for your job's state by name (for example 'how long is a ticket good for in Texas'), or open Locates and tap Rules for the state. Federal OSHA adds its own duty in every state: find out where underground lines are before opening an excavation, and protect, support or remove them while it is open (29 CFR 1926.651(b)). The ticket, the 811 center and the state law govern; this is a plain-language summary.", "title": "811 before you dig: what is the same everywhere and what changes by state", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "State one-call laws as listed in the app's state rules table (51 rows, checked 2026-11-19); 29 CFR 1926.651(b)", "confidence": "high"}$kb$::jsonb
   where version = 'b3e91f6c47d2' and ord = 2835 and chunk->>'id' = $kb$dig-basics-1$kb$ and md5(chunk::text) = md5($kb${"id": "dig-basics-1", "url": "https://www.osha.gov/laws-regs/regulations/standardnumber/1926/1926.651", "text": "Every state has a one-call law and 811 reaches the right center from anywhere in the country. The steps are the same everywhere: mark your dig area in white, call or go online before you dig, wait the legal notice time, check that every utility has marked or answered, dig by hand or vacuum inside the tolerance zone, keep the marks visible, and renew the ticket before it runs out. What changes by state is the numbers. Of the 51 state tables in the app (50 states and DC, checked 2026-11-19): the wait is 2 working days in 28 states and 3 in 13, and longer in a few; ticket life runs from about two weeks to 60 days, counted in working days in some states and calendar days in others, and from the call in some and from the legal dig date in others; the tolerance zone is 18 inches each side in about as many states as 24 inches, measured from the mark in some and from the outside edge of the line in others. So never carry one state's numbers to the next job: ask for your job's state by name (for example 'how long is a ticket good for in Texas'), or open Locates and tap Rules for the state. Federal OSHA adds its own duty in every state: find out where underground lines are before opening an excavation, and protect, support or remove them while it is open (29 CFR 1926.651(b)). The ticket, the 811 center and the state law govern; this is a plain-language summary.", "title": "811 before you dig: what is the same everywhere and what changes by state", "topic": "811 dig rules by state: wait before digging, ticket life, tolerance zone", "source": "State one-call laws as listed in the app's state rules table (51 rows, checked 2026-11-19); 29 CFR 1926.651(b)", "confidence": "high"}$kb$::jsonb::text);
  get diagnostics vk = row_count; if vk <> 1 then raise exception 'FAIL: row % is not the expected live text', 2835; end if;
  -- ord 2839: plan-trench-depth-1 -> osha-pl-trench-states-2
  update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "osha-pl-trench-states-2", "state": "US", "tier": "core", "supersedes": "plan-trench-depth-1", "title": "State OSHA plans and the trench rule: which plan states follow federal 5 ft, which differ, which are not checked", "topic": "Trench and excavation rules: which states follow federal OSHA", "text": "Twenty-one states run their own OSHA plan for private construction crews. A plan must be at least as protective as federal OSHA (protection from 5 ft, 29 CFR 1926.652(a)(1)) and may be stricter, so name the plan as the source. Use only the line for the job's state. As checked by 2026-11-20. The plan adopts the federal excavation rule, so 5 ft: Alaska, Arizona (R20-5-601), Kentucky (803 KAR 2:415), Minnesota (MNOSHA trenching fact sheet: no state difference), Nevada, New Mexico (11.5.3.9 NMAC), Tennessee, Utah (R614-1-4), Indiana (620 IAC 1-1-30 items 7 and 18 adopt 29 CFR 1926.650-652, in force March 5, 1990, with no Indiana depth or permit of its own; OSHA's page lists an Indiana excavation standard that was not identified, not confirmed: ask IOSHA). No excavation rule of their own on the list (agency pages, not each code read line by line), so 5 ft: Hawaii, North Carolina, Virginia. Differ, each has its own card: Washington, California, Michigan, Maryland, South Carolina, Oregon. Not checked: Iowa, Vermont, Wyoming: federal 5 ft is the floor; ask the state plan.", "source": "29 CFR 1926.652(a)(1); osha.gov/stateplans; AZ R20-5-601; UT R614-1-4; NM 11.5.3.9 NMAC; KY 803 KAR 2:415; 620 IAC 1-1-30 (54 FR); MNOSHA trenching fact sheet; checked 2026-11-20", "url": "https://www.osha.gov/stateplans", "checked": "2026-11-20", "edition": "State plan rules as read 2026-11-20", "confidence": "medium", "kind": "summary", "license": "gov-us", "unconfirmed": "yes", "note": "Supersedes plan-trench-depth-1 (same ord). Takes the trench facts of sp-in-trench-1 and sp-mn-trench-1 (both retired)."}$kb$::jsonb
   where version = 'b3e91f6c47d2' and ord = 2839 and chunk->>'id' = $kb$plan-trench-depth-1$kb$ and md5(chunk::text) = md5($kb${"id": "plan-trench-depth-1", "url": "https://www.osha.gov/stateplans", "text": "Federal OSHA requires a protective system (sloping, benching, shoring or a shield) in an excavation 5 ft or deeper unless it is entirely in stable rock, and in a shallower one when the competent person sees a cave-in hazard (29 CFR 1926.652). Twenty-one states run their own OSHA plan for private construction crews; a plan must be at least as protective as federal and may be stricter, so on those jobs cite the state rule. What has been checked against the state's own rule text so far (as of 2026-11-20): Washington requires protection at 4 ft and, since June 1, 2026, a written trench work plan and a competent person on site during trench work; California keeps 5 ft and adds a Cal/OSHA permit for excavations 5 ft or deeper that people enter; Michigan uses its own Part 9 (slope or support over 5 ft, with its own angle table); Arizona, Nevada, New Mexico, Oregon and Utah adopt the federal excavation standard, so 5 ft; Alaska, Kentucky, Minnesota and Tennessee adopt the federal rule and Hawaii, North Carolina and Virginia list no excavation rule of their own (from OSHA's and the agencies' pages, not each state code read line by line), so 5 ft; South Carolina uses the federal text and adds training to the competent person definition. Not yet checked: Indiana, Iowa, Maryland (a state supplement to the federal rule exists and was not read), Vermont and Wyoming; treat federal 5 ft as the floor there and ask the state agency or your safety person whether the plan adds anything. In every state the competent person and your company program decide what protection a trench gets.", "title": "State OSHA plans and trench protection depth: which rule book applies on your job", "topic": "State OSHA plans: where trench and confined space rules differ from federal OSHA", "source": "29 CFR 1926.652(a)(1); osha.gov/stateplans; Wash. Admin. Code 296-155-657; 8 CCR 341; Mich. Admin. Code R 408.40941; AZ R20-5-601; UT R614-1-4; OR 437-003-0001; NM 11.5.3.9 NMAC; checked 2026-11-20", "confidence": "medium", "supersedes": "plan-trench-depth-1"}$kb$::jsonb::text);
  get diagnostics vk = row_count; if vk <> 1 then raise exception 'FAIL: row % is not the expected live text', 2839; end if;
  -- ord 2841: dig-ca-penalties-1 -> dig-ca-penalties-2
  update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "dig-ca-penalties-2", "state": "CA", "tier": "core", "supersedes": "dig-ca-penalties-1", "title": "California 811: the fine for digging without calling 811, and who enforces (Gov Code 4216.6, Dig Safe Board)", "topic": "811 penalties, exemptions and design tickets", "text": "California fines for breaking the dig law (Gov. Code 4216.6(a)): a negligent violation, up to $10,000; a knowing and willful violation, up to $50,000; a knowing and willful violation that damages a gas or hazardous liquid line and lets flammable, toxic or corrosive gas or liquid escape, up to $100,000. Who enforces (4216.6(c) to (e)): the Contractors State License Board for licensed contractors (a license can be on the line); the Public Utilities Commission for gas, electric and water corporations; the State Fire Marshal for hazardous liquid pipeline operators; local boards for local agencies; and, since July 1, 2020, the Underground Facilities Safe Excavation Board (the Dig Safe Board, under the Office of the State Fire Marshal) for everyone else. The Board also investigates damages and near misses reported to it and recommends. The Attorney General or a district attorney can also sue. Repair costs and injury claims are separate. Typical: no valid ticket, digging before every operator has responded, machine digging in the tolerance zone, no delineation, not reporting damage. Keep the ticket number on the daily report, photos of the marks, and a record of hand-dug potholes.", "source": "Cal. Gov. Code 4216.6(a), (b), (c), (d), (e)", "url": "https://leginfo.legislature.ca.gov/faces/codes_displaySection.xhtml?lawCode=GOV&sectionNum=4216.6.", "checked": "2026-11-20", "edition": "Section as updated January 1, 2025", "confidence": "high", "kind": "summary", "license": "gov-state", "note": "Merges dig-ca-penalties-1 (this ord) and ca-dig-alert-4216-9 (retired): the same section said twice."}$kb$::jsonb
   where version = 'b3e91f6c47d2' and ord = 2841 and chunk->>'id' = $kb$dig-ca-penalties-1$kb$ and md5(chunk::text) = md5($kb${"id": "dig-ca-penalties-1", "url": "https://california.public.law/codes/ca_gov't_code_section_4216.6", "kind": "summary", "text": "California fines for breaking the dig law (Gov. Code 4216.6(a)): a negligent violation, up to $10,000; a knowing and willful violation, up to $50,000; a knowing and willful violation that damages a gas or hazardous liquid line and lets flammable, toxic or corrosive gas or liquid escape, up to $100,000. Who enforces: the Contractors State License Board for contractors; the Public Utilities Commission for gas, electric and water corporations; the State Fire Marshal for hazardous liquid pipelines; local boards for local agencies; and the Underground Safe Excavation Board (\"Dig Safe Board\") for everyone else, since July 1, 2020. The Attorney General or a district attorney can also sue. On top of fines, the excavator can owe the repair cost and other damages. A contractor's license can be on the line with the CSLB. The Board also investigates near misses and damages reported to it.", "tier": "core", "state": "CA", "title": "California 811: the fine for digging without calling 811, and who enforces", "topic": "811 penalties, exemptions and design tickets", "source": "Cal. Gov. Code 4216.6 (california.public.law copy, section updated Jan 1, 2025)", "checked": "2026-11-20", "edition": "Section as updated January 1, 2025", "license": "gov-state", "confidence": "high"}$kb$::jsonb::text);
  get diagnostics vk = row_count; if vk <> 1 then raise exception 'FAIL: row % is not the expected live text', 2841; end if;
  -- ord 2979: sp-ca-trench-1 (edited in place)
  update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "sp-ca-trench-1", "state": "CA", "tier": "core", "supersedes": "sp-ca-trench-1", "title": "California trench protection depth (5 ft, same as federal) and the Cal/OSHA excavation permit (8 CCR 341)", "topic": "State safety plan: trench and excavation", "text": "California (Cal/OSHA) requires a protective system unless the excavation is entirely in stable rock, or under 5 feet with no sign of a potential cave-in on a competent person's examination (8 CCR 1541.1(a)(1)): the same 5 ft test as federal, with the same slopes (1541.1 Appendix B). What California adds is a permit: 8 CCR 1539 sends excavation permits to 8 CCR 341, which requires a Cal/OSHA permit before building a trench or excavation 5 ft or deeper into which any person is required to descend (341(d)(5)(A)). It is an annual permit or a one-job project permit from the district office (application and fee, 341.1); an annual holder notifies the Division before each new site. Exempt (341(e)): government bodies, PUC-regulated utilities, emergency repair of underground facilities, excavations nobody has to enter, graves and pools. Greenbook 306-3.1 repeats the requirement. Keep the permit number with the job paperwork; the permit does not replace the competent person or the protective system. Shields: dig no more than 2 ft below the bottom of the support (1541.1(e)(2)(A)).", "source": "8 CCR 1541.1(a)(1), (e)(2)(A); 8 CCR 1539; 8 CCR 341(c), (d)(5)(A), (e); 341.1; Greenbook 306-3.1", "url": "https://www.dir.ca.gov/title8/341.html", "checked": "2026-11-20", "edition": "Title 8 as posted on dir.ca.gov, read 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-state", "note": "Takes in ca-cal-osha-trench-and-confined-1 and cal-1 (both retired: the same permit)."}$kb$::jsonb
   where version = 'b3e91f6c47d2' and ord = 2979 and chunk->>'id' = $kb$sp-ca-trench-1$kb$ and md5(chunk::text) = md5($kb${"id": "sp-ca-trench-1", "url": "https://dir.ca.gov/Title8/1541_1.html", "kind": "summary", "text": "California (Cal/OSHA) requires a protective system for each employee in an excavation unless it is made entirely in stable rock, or it is less than 5 feet deep and a competent person's examination of the ground finds no sign of a potential cave-in (8 CCR 1541.1(a)(1)). That is the same 5 ft test as federal OSHA. California's sloping table (8 CCR 1541.1 Appendix B) has the same slopes as the federal one. What California adds is a permit: 8 CCR 1539 sends excavation and trench permits to 8 CCR 341, which requires a Cal/OSHA permit before building a trench or excavation 5 ft or deeper into which any person is required to descend (341(d)(5)(A)); trenches for emergency repair of underground facilities are exempt (341(e)). The trench shield rule matches the federal one: dig no more than 2 feet below the bottom of the support (8 CCR 1541.1(e)(2)(A)).", "tier": "core", "state": "CA", "title": "California trench protection depth and the Cal/OSHA excavation permit", "topic": "State safety plan: trench and excavation", "source": "8 CCR 1541.1(a)(1), (e)(2)(A); 8 CCR 1539; 8 CCR 341(d)(5)(A), (e)", "checked": "2026-11-20", "edition": "Title 8 CCR, section text read 2026-11-20 (Register 2011, No. 50)", "license": "gov-state", "confidence": "high"}$kb$::jsonb::text);
  get diagnostics vk = row_count; if vk <> 1 then raise exception 'FAIL: row % is not the expected live text', 2979; end if;
  -- ord 2981: sp-ca-trench-other-1 (edited in place)
  update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "sp-ca-trench-other-1", "state": "CA", "tier": "core", "supersedes": "sp-ca-trench-other-1", "title": "California trench rules that match federal (ladders, air, spoil, inspections) and the crossing rule (Title 8 Article 6)", "topic": "State safety plan: trench and excavation", "text": "California's excavation standard is Title 8 Construction Safety Orders Article 6: 1539 (permits), 1540 (definitions), 1541 (general requirements) and 1541.1 (protective systems, Appendices A to F matching the federal ones; appendix options to 20 ft, an engineer beyond). It keeps the federal numbers: a stairway, ladder or ramp in trenches 4 feet or deeper within 25 feet of lateral travel (1541(c)(2)); air testing before entry deeper than 4 feet where a hazard could exist, limits 19.5 percent oxygen and 20 percent of the LFL (1541(g)(1)(A)); spoil and equipment at least 2 feet from the edge (1541(j)(2)); daily competent-person inspections before work, as needed and after rain (1541(k)(1)). Crossings differ: walkways or bridges with standard guardrails where people or equipment cross excavations more than 6 feet deep and wider than 30 inches (1541(l)(1)); remote excavations, wells, pits and shafts barricaded or covered (1541(l)(2)). The federal crossing rule has no width (29 CFR 1926.651(l)). The 5 ft permit is in section 341.", "source": "8 CCR 1539, 1540, 1541(c)(2), (g)(1)(A), (j)(2), (k)(1), (l)(1)-(2), 1541.1 compared with 29 CFR 1926.650-652", "url": "https://dir.ca.gov/title8/1541.html", "checked": "2026-11-20", "edition": "Title 8 as posted on dir.ca.gov, read 2026-11-20", "confidence": "high", "kind": "summary", "license": "gov-state", "note": "Takes in ca-cal-osha-trench-and-confined-2 (retired). Its 1541(b) one-call sentence is in sp-ca-trench-dig-1."}$kb$::jsonb
   where version = 'b3e91f6c47d2' and ord = 2981 and chunk->>'id' = $kb$sp-ca-trench-other-1$kb$ and md5(chunk::text) = md5($kb${"id": "sp-ca-trench-other-1", "url": "https://dir.ca.gov/title8/1541.html", "kind": "summary", "text": "California's 8 CCR 1541 keeps the federal numbers for the everyday trench rules: a stairway, ladder, ramp or other safe way out in trenches 4 feet or deeper, within 25 feet of lateral travel (1541(c)(2)); air testing before entering excavations deeper than 4 feet where oxygen under 19.5 percent or a hazardous atmosphere could reasonably be expected (1541(g)(1)(A)); spoil, materials and equipment at least 2 feet from the edge or held back by retaining devices (1541(j)(2)); and daily inspections by a competent person before work, as needed during the shift and after rain (1541(k)(1)). Crossings are worded differently: walkways or bridges with standard guardrails are required where employees or equipment cross over excavations more than 6 feet deep and wider than 30 inches (1541(l)(1)); remote excavations, wells, pits and shafts are barricaded or covered (1541(l)(2)). The federal crossing rule has no width (29 CFR 1926.651(l)).", "tier": "core", "state": "CA", "title": "California trench ladders, air testing, spoil setback and crossings", "topic": "State safety plan: trench and excavation", "source": "8 CCR 1541(c)(2), (g)(1)(A), (j)(2), (k)(1), (l)(1)-(2)", "checked": "2026-11-20", "edition": "Title 8 CCR, last amended operative 5-31-2012 (Register 2012, No. 18)", "license": "gov-state", "confidence": "high"}$kb$::jsonb::text);
  get diagnostics vk = row_count; if vk <> 1 then raise exception 'FAIL: row % is not the expected live text', 2981; end if;
  -- ord 2987: sp-wa-trench-1 (edited in place)
  update pb_ai.kb_chunks set lib = 'field', chunk = $kb${"id": "sp-wa-trench-1", "state": "WA", "tier": "core", "supersedes": "sp-wa-trench-1", "title": "Washington trench protection starts at 4 feet (stricter than federal 5 ft); walkway guardrails at 4 ft", "topic": "State safety plan: trench and excavation", "text": "Washington (L&I, DOSH) requires a protective system for each employee in an excavation unless it is made entirely in stable rock, or it is \"less than 4 feet (1.22m) in depth and examination of the ground by a competent person provides no indication of a potential cave-in\" (WAC 296-155-657(1)(a)). So the depth is 4 ft, one foot shallower than the federal 5 ft (29 CFR 1926.652(a)(1)). The 2 ft rules match federal: dig no more than two feet below the bottom of a support system or a shield, and only if it is designed for the full depth and no soil is being lost (657(5)(b), (7)(b)). An engineer designs slopes over 20 ft. Guardrails are required \"where walkways are four feet or more above lower levels\" (296-155-655(12)); federal uses 6 ft (1926.651(l)). Utilities are located before opening the excavation and found exactly by safe means as digging gets close (655(2)). Same numbers as federal: a way out within 25 ft at 4 ft deep (655(3)(b)), air testing over 4 ft (655(7)(a)(i)), equipment 2 ft from the edge (655(10)(b)), daily inspections and after every rainstorm (655(11)(a)).", "source": "WAC 296-155-657(1)(a), (5)(b), (7)(b); WAC 296-155-655(2), (3)(b), (7)(a)(i), (10)(b), (11)(a), (12)", "url": "https://lawfilesext.leg.wa.gov/Law/WAC/WAC%20296%20%20TITLE/WAC%20296%20-155%20%20CHAPTER/WAC%20296%20-155%20-657.htm", "checked": "2026-11-20", "edition": "WAC 296-155-657, WSR 16-09-085, effective 5/20/2016; WAC 296-155-655 as amended eff. June 1, 2026", "effective": "2016-05-20", "confidence": "high", "kind": "summary", "license": "gov-state", "note": "Takes in sp-wa-trench-other-1 (retired). The Table N-1 sentence moved to sp-wa-trench-slope-1, which already says it in full."}$kb$::jsonb
   where version = 'b3e91f6c47d2' and ord = 2987 and chunk->>'id' = $kb$sp-wa-trench-1$kb$ and md5(chunk::text) = md5($kb${"id": "sp-wa-trench-1", "url": "https://lawfilesext.leg.wa.gov/Law/WAC/WAC%20296%20%20TITLE/WAC%20296%20-155%20%20CHAPTER/WAC%20296%20-155%20-657.htm", "kind": "summary", "text": "Washington (L&I, DOSH) requires a protective system for each employee in an excavation unless it is made entirely in stable rock, or it is \"less than 4 feet (1.22m) in depth and examination of the ground by a competent person provides no indication of a potential cave-in\" (WAC 296-155-657(1)(a)). So in this state the depth is 4 ft, one foot shallower than the federal 5 ft in 29 CFR 1926.652(a)(1). The 2 ft rules match federal: dig no more than two feet below the bottom of a support system or a shield, and only if it is designed for the full depth and no soil is being lost (296-155-657(5)(b), (7)(b)). The state's sloping table (Table N-1, WAC 296-155-66403) has the federal slopes but no short-term 1/2 to 1 Type A row (read by an earlier check on 2026-11-20). An engineer designs slopes over 20 ft.", "tier": "core", "state": "WA", "title": "Washington trench protection starts at 4 feet", "topic": "State safety plan: trench and excavation", "source": "WAC 296-155-657(1)(a), (5)(b), (7)(b); WAC 296-155-66403 Table N-1", "checked": "2026-11-20", "edition": "WAC 296-155-657, WSR 16-09-085, effective 5/20/2016", "license": "gov-state", "effective": "2016-05-20", "confidence": "high"}$kb$::jsonb::text);
